def solve():
    solutions = []
    for p in range(2, 1000):
        if is_prime(p):
            val = 4 * p**3 - 3
            k = int(val**0.5)
            if k*k == val:
                q1 = (1 + k) // 2
                q2 = (1 - k) // 2
                if is_prime(q1) and q1 != p:
                    solutions.append((q1, p))
                if is_prime(q2) and q2 != p:
